// Quantity take-off — one flooring quantity from the deterministic engine
// (scripts/drawing-ocr/quantity_core.py) through the app's EXISTING path:
// import (parseAnalysisV1) -> recompute (measurementValidator via
// calculationAdvisory / lineEvidence) -> review -> Apply plan -> the real
// applyReviewPlan() write -> the persisted boq_line -> the CSV and PDF
// renderers. Only the Supabase client is mocked (same boundary as
// applySourceToExport.integration.test.ts); every app function is real.
//
// The fixture is generated by the engine from a made-up schedule
// (synthetic_fixture() in scripts/drawing-ocr/test_quantity_core.py, which
// fails if it drifts). Synthetic data: this proves the contract and the
// workflow, not take-off accuracy on real drawings.
import { describe, it, expect, vi, beforeEach } from "vitest";

const boqLineStore = new Map<string, Record<string, unknown>>();

vi.mock("@/integrations/supabase/client", () => ({
  supabase: {
    auth: { getUser: async () => ({ data: { user: { id: "user-1" } } }) },
    from: (table: string) => ({
      insert: (payload: Record<string, unknown>) => {
        const result = table === "boq_line" ? { data: { id: "new-line-1" }, error: null } : { error: null };
        if (table === "boq_line") boqLineStore.set("new-line-1", payload);
        return {
          select: () => ({ single: async () => result }),
          then: (onFulfilled: (v: unknown) => unknown) => Promise.resolve(result).then(onFulfilled),
        };
      },
      update: () => ({ eq: () => Promise.resolve({ error: null }) }),
      select: () => {
        const b = {
          eq: () => b, not: () => b,
          single: async () => (table === "boq" ? { data: { project_id: "project-1" }, error: null } : { data: null, error: null }),
          maybeSingle: async () => ({ data: null, error: null }),
          then: (resolve: (v: { data: unknown; error: null }) => void) => resolve({ data: [], error: null }),
        };
        return b;
      },
    }),
  },
}));

import fixture from "./__fixtures__/quantityTakeoffSynthetic.json";
import { parseAnalysisV1, type AnalysisItemV1 } from "./analysisSchemaV1";
import { validateItemCalculation, calculationAdvisoryText } from "./calculationAdvisory";
import { buildApplyPlan, applyReviewPlan } from "./applyReview";
import { evidenceForLine, explainCalculation, type EvidenceItem } from "../lineEvidence";
import { REVIEW_CORRECTED_BASIS, REVIEW_VERIFIED_BASIS } from "../quantity";
import { buildBoqCsv, buildDsrQuoteHtml, computeCommercials, type CsvRow, type QuoteItem } from "../boqDsrDocument";
import type { StoredReviewItem } from "./reviewStore";

const parsed = parseAnalysisV1(JSON.stringify(fixture));
const items = parsed.analysis!.items;
const byKey = (k: string) => items.find((i) => i.key === k)!;
const stored = (id: string, ai: AnalysisItemV1, o: Partial<StoredReviewItem> = {}): StoredReviewItem => ({ id, ai, reviewStatus: "PENDING_REVIEW", ...o });

beforeEach(() => boqLineStore.clear());

describe("quantity take-off output through import and recompute", () => {
  it("imports with no warnings; only the calculated finish is MEASURED", () => {
    expect(parsed.ok).toBe(true);
    expect(parsed.warnings).toEqual([]);
    expect(parsed.calculationDataDroppedCount).toBe(0);
    expect(items.map((i) => [i.key, i.aiStatus, i.quantity])).toEqual([
      ["FLOOR:FL-1", "MEASURED", 200.5],
      ["FLOOR:FL-2", "PENDING", null],
      ["FLOOR:FL-3", "PENDING", null],
      ["FLOOR:FL-4", "PENDING", null],
      ["SKIRT:Oak 3in", "PENDING", null],
      ["SKIRT:Tile 4in", "PENDING", null],
    ]);
  });

  it("the app recomputes the calculated quantity from its recorded inputs", () => {
    const fl1 = byKey("FLOOR:FL-1");
    expect(fl1.calculationData?.formula).toBe("SUM_OF_SEGMENTS");
    const v = validateItemCalculation(fl1);
    expect(v?.comparison?.outcome).toBe("EXACT_MATCH");
    expect(calculationAdvisoryText(v)).toBe("Arithmetic matches — not drawing verification.");
    expect(explainCalculation(fl1)?.expression).toContain("R1 — Room A area 120 sqft + R2 — Room B area 80.5 sqft");
  });

  it("unresolved quantities carry their reasons and no calculation the app could mistake for a result", () => {
    for (const k of ["FLOOR:FL-2", "FLOOR:FL-3", "FLOOR:FL-4", "SKIRT:Oak 3in"]) {
      const it = byKey(k);
      expect(it.calculationData).toBeUndefined();
      expect(validateItemCalculation(it)).toBeNull();
      expect(it.notes).toMatch(/^(Ambiguous|Insufficient): /);
    }
    expect(byKey("FLOOR:FL-3").unit).toBe("sqft"); // keeps its schedule's unit while unresolved
  });
});

describe("quantity take-off through review, Apply, the persisted line and export", () => {
  it("a verified flooring quantity is written with its unit, method and key, and exports unchanged", async () => {
    const fl1 = stored("ri-fl1", byKey("FLOOR:FL-1"), { reviewStatus: "VERIFIED" });
    const plan = buildApplyPlan([fl1], []);
    expect(plan[0].classification).toBe("NEW_LINE");
    const res = await applyReviewPlan({ boqId: "boq-1", candidates: plan, selectedIds: new Set(["ri-fl1"]) });
    expect(res.appliedCount).toBe(1);

    const line = boqLineStore.get("new-line-1")!;
    expect(line).toMatchObject({ qty: 200.5, unit: "sqft", external_key: "FLOOR:FL-1", quantity_status: "MEASURED", basis: REVIEW_VERIFIED_BASIS });
    expect(String(line.description)).toContain("Flooring FL-1 — Oak strip");

    // the persisted line links back to its reviewed item, whose calculation the app recomputes
    const evidence = evidenceForLine(
      { external_key: line.external_key as string, qty: line.qty as number, unit: line.unit as string },
      [{ id: "ri-fl1", runId: "run-1", ai: fl1.ai, reviewStatus: "VERIFIED" } satisfies EvidenceItem],
    );
    expect(evidence.kind).toBe("linked");
    if (evidence.kind === "linked") {
      expect(evidence.calculation?.advisory).toBe("Arithmetic matches — not drawing verification.");
      expect(evidence.calculation?.expression).toContain("80.5 sqft");
    }

    const csvRow: CsvRow = { subhead: "1.00 Flooring", itemNo: "1.01", code: null, spec: String(line.description), unit: line.unit as string, qty: line.qty as number, rate: null };
    const csvLine = buildBoqCsv([csvRow], { boqName: "Test BOQ", generatedOn: "1 Jan 2026" }).split("\r\n")[4];
    expect(csvLine).toContain("sqft");
    expect(csvLine).toContain("200.5");

    const quoteItem: QuoteItem = { no: "1.01", code: null, spec: String(line.description), qty: line.qty as number, unit: line.unit as string, rate: null, amount: null };
    const html = buildDsrQuoteHtml({
      boqName: "Test BOQ", generatedOn: "1 Jan 2026",
      subheads: [{ no: 1, name: "Flooring", subtotal: 0, lines: [quoteItem] }],
      abstract: [{ no: 1, name: "Flooring", amount: 0 }],
      commercials: computeCommercials(0, { costIndexPct: 0, contingencyPct: 0, overheadPct: 0, cessPct: 0, gstPct: 18 }),
    }, { autoPrint: false });
    expect(html).toContain("Flooring FL-1");
    expect(html).toContain("200.5");
  });

  it("unresolved quantities are never applied while pending review", () => {
    const pending = ["FLOOR:FL-2", "FLOOR:FL-3", "SKIRT:Oak 3in"].map((k, i) => stored(`ri-p${i}`, byKey(k)));
    expect(buildApplyPlan(pending, []).map((c) => c.classification)).toEqual(["NOT_ELIGIBLE", "NOT_ELIGIBLE", "NOT_ELIGIBLE"]);
  });

  it("an unresolved quantity reaches the BOQ only through an explicit reviewer value, recorded as a correction", async () => {
    // e.g. the reviewer measures FL-3's missing room and enters the total themselves
    const fl3 = stored("ri-fl3", byKey("FLOOR:FL-3"), { reviewStatus: "EDITED", reviewer: { quantity: 64 } });
    const plan = buildApplyPlan([fl3], []);
    expect(plan[0].classification).toBe("NEW_LINE");
    await applyReviewPlan({ boqId: "boq-1", candidates: plan, selectedIds: new Set(["ri-fl3"]) });
    expect(boqLineStore.get("new-line-1")).toMatchObject({ qty: 64, unit: "sqft", basis: REVIEW_CORRECTED_BASIS, external_key: "FLOOR:FL-3" });
    // the engine's own record of why it couldn't calculate stays with the reviewed item
    expect(fl3.ai.notes).toContain("nothing printed in column SFT");
  });
});
